//! pci.library's functions: the machine's PCI functions found, claimed,
//! their configuration space read and written, their interrupts hooked.
//! Open it with OpenLibrary("pci.library", 1); the structures are in
//! sdk.pci.
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/pci_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const exec = @import("../libs/exec/exec.zig");
const pci = @import("../libs/pci/pci.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "pci.library";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const FindPCIDevice = libraries.lvo(4);
    pub const FindPCIClass = libraries.lvo(5);
    pub const ReadPCIConfig = libraries.lvo(6);
    pub const WritePCIConfig = libraries.lvo(7);
    pub const ClaimPCIDevice = libraries.lvo(8);
    pub const ReleasePCIDevice = libraries.lvo(9);
    pub const AddPCIIntServer = libraries.lvo(10);
    pub const RemPCIIntServer = libraries.lvo(11);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const FindPCIDevice = *const fn (*PCIBase, ?*pci.PCIDevice, u32, u32) callconv(.c) ?*pci.PCIDevice;
    pub const FindPCIClass = *const fn (*PCIBase, ?*pci.PCIDevice, u32, u32) callconv(.c) ?*pci.PCIDevice;
    pub const ReadPCIConfig = *const fn (*PCIBase, *pci.PCIDevice, u32, u32) callconv(.c) u32;
    pub const WritePCIConfig = *const fn (*PCIBase, *pci.PCIDevice, u32, u32, u32) callconv(.c) void;
    pub const ClaimPCIDevice = *const fn (*PCIBase, *pci.PCIDevice, [*:0]const u8) callconv(.c) ?[*:0]const u8;
    pub const ReleasePCIDevice = *const fn (*PCIBase, *pci.PCIDevice) callconv(.c) void;
    pub const AddPCIIntServer = *const fn (*PCIBase, *pci.PCIDevice, *exec.Interrupt) callconv(.c) bool;
    pub const RemPCIIntServer = *const fn (*PCIBase, *pci.PCIDevice, *exec.Interrupt) callconv(.c) void;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const PCIBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *PCIBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// The function after `previous` (null: from the first) whose vendor and
    /// device are these (PCI_ANY: any), or null.
    pub fn FindPCIDevice(self: *PCIBase, previous: ?*pci.PCIDevice, vendor: u32, device: u32) ?*pci.PCIDevice {
        return libraries.call(self, LVO.FindPCIDevice, Fn.FindPCIDevice, .{ previous, vendor, device });
    }

    /// The function after `previous` (null: from the first) whose class code,
    /// masked with `mask`, is `class_code`, or null.
    pub fn FindPCIClass(self: *PCIBase, previous: ?*pci.PCIDevice, class_code: u32, mask: u32) ?*pci.PCIDevice {
        return libraries.call(self, LVO.FindPCIClass, Fn.FindPCIClass, .{ previous, class_code, mask });
    }

    /// `size` bytes (1, 2 or 4) of the function's configuration space at
    /// `offset`, which they are aligned to.
    pub fn ReadPCIConfig(self: *PCIBase, device: *pci.PCIDevice, offset: u32, size: u32) u32 {
        return libraries.call(self, LVO.ReadPCIConfig, Fn.ReadPCIConfig, .{ device, offset, size });
    }

    /// `size` bytes (1, 2 or 4) of `value` into the function's configuration
    /// space at `offset`, which they are aligned to.
    pub fn WritePCIConfig(self: *PCIBase, device: *pci.PCIDevice, offset: u32, size: u32, value: u32) void {
        return libraries.call(self, LVO.WritePCIConfig, Fn.WritePCIConfig, .{ device, offset, size, value });
    }

    /// The function taken by the driver called `owner`: null, or the name of
    /// the one that has it.
    pub fn ClaimPCIDevice(self: *PCIBase, device: *pci.PCIDevice, owner: [*:0]const u8) ?[*:0]const u8 {
        return libraries.call(self, LVO.ClaimPCIDevice, Fn.ClaimPCIDevice, .{ device, owner });
    }

    /// A claimed function given back, its bus mastering off.
    pub fn ReleasePCIDevice(self: *PCIBase, device: *pci.PCIDevice) void {
        return libraries.call(self, LVO.ReleasePCIDevice, Fn.ReleasePCIDevice, .{device});
    }

    /// `server` run whenever the function raises its INTx line; false if it
    /// has none.
    pub fn AddPCIIntServer(self: *PCIBase, device: *pci.PCIDevice, server: *exec.Interrupt) bool {
        return libraries.call(self, LVO.AddPCIIntServer, Fn.AddPCIIntServer, .{ device, server });
    }

    /// The server taken off the function's line.
    pub fn RemPCIIntServer(self: *PCIBase, device: *pci.PCIDevice, server: *exec.Interrupt) void {
        return libraries.call(self, LVO.RemPCIIntServer, Fn.RemPCIIntServer, .{ device, server });
    }
};
